<?php
$loanStatuses = ['all', 'pending', 'approved', 'active', 'settled', 'rejected'];
$statusFilter = (string)($_GET['status'] ?? 'all');
if (!in_array($statusFilter, $loanStatuses, true)) $statusFilter = 'all';
$memberSearch = trim((string)($_GET['member'] ?? ''));

if ($user['role'] === 'admin') {
    $sql = "SELECT l.*, m.full_name, m.staff_id, COALESCE((SELECT SUM(r.amount) FROM loan_repayments r WHERE r.loan_id = l.id), 0) AS repaid FROM loans l JOIN members m ON m.id = l.member_id";
    $conditions = [];
    $params = [];
    if ($statusFilter !== 'all') { $conditions[] = 'l.status = ?'; $params[] = $statusFilter; }
    if ($memberSearch !== '') { $conditions[] = '(m.full_name LIKE ? OR m.staff_id LIKE ?)'; $params[] = '%' . $memberSearch . '%'; $params[] = '%' . $memberSearch . '%'; }
    if ($conditions) $sql .= ' WHERE ' . implode(' AND ', $conditions);
    $sql .= " ORDER BY (l.status = 'pending') DESC, l.created_at DESC LIMIT 250";
    $stmt = db()->prepare($sql); $stmt->execute($params); $loans = $stmt->fetchAll();
    $repaymentSql = "SELECT r.amount, r.payment_reference, r.paid_at, m.full_name, m.staff_id FROM loan_repayments r JOIN loans l ON l.id = r.loan_id JOIN members m ON m.id = l.member_id";
    $repaymentParams = [];
    if ($memberSearch !== '') { $repaymentSql .= ' WHERE (m.full_name LIKE ? OR m.staff_id LIKE ?)'; $repaymentParams = ['%' . $memberSearch . '%', '%' . $memberSearch . '%']; }
    $repaymentSql .= ' ORDER BY r.paid_at DESC LIMIT 250';
    $stmt = db()->prepare($repaymentSql); $stmt->execute($repaymentParams); $repayments = $stmt->fetchAll();
} else {
    $sql = "SELECT l.*, COALESCE((SELECT SUM(r.amount) FROM loan_repayments r WHERE r.loan_id = l.id), 0) AS repaid FROM loans l WHERE l.member_id = ?";
    $params = [$user['member_id']];
    if ($statusFilter !== 'all') { $sql .= ' AND l.status = ?'; $params[] = $statusFilter; }
    $sql .= ' ORDER BY l.created_at DESC LIMIT 100';
    $stmt = db()->prepare($sql); $stmt->execute($params); $loans = $stmt->fetchAll();
    $stmt = db()->prepare('SELECT r.amount, r.payment_reference, r.paid_at FROM loan_repayments r JOIN loans l ON l.id = r.loan_id WHERE l.member_id = ? ORDER BY r.paid_at DESC LIMIT 100');
    $stmt->execute([$user['member_id']]); $repayments = $stmt->fetchAll();
}
$outstandingBalance = 0.0; $activeLoans = 0;
foreach ($loans as $loan) if (in_array($loan['status'], ['approved', 'active'], true) && $loan['principal_amount'] !== null) { $activeLoans++; $outstandingBalance += max(0, (float)$loan['principal_amount'] - (float)$loan['repaid']); }
?>
<div class="dashboard-heading"><div><p class="eyebrow"><?= $user['role'] === 'admin' ? 'Administrator portal' : 'Member portal' ?></p><h1>Loans & repayments</h1><p><?= $user['role'] === 'admin' ? 'Review applications, monitor balances, and record repayments.' : 'Apply for a loan and track your repayment status.' ?></p></div></div>
<?php if ($user['role'] === 'member' && $user['member_status'] === 'active'): ?><section class="panel form-panel"><h2>Apply for a loan</h2><form method="post" class="form-stack"><?= csrf_field() ?><input type="hidden" name="action" value="loan_application"><label>Requested amount (₦)<input type="number" name="amount" min="0.01" step="0.01" required></label><label>Purpose<textarea name="purpose" rows="3" maxlength="2000" required></textarea></label><button class="button button-primary" type="submit">Submit loan application</button></form></section><?php endif; ?>
<?php if ($user['role'] === 'admin'): ?><div class="loan-overview-grid"><?php endif; ?><section class="stats-grid loan-stats"><article class="stat-card"><span><?= $user['role'] === 'admin' ? 'Loans shown' : 'Your loans shown' ?></span><strong><?= number_format(count($loans)) ?></strong><small><?= $statusFilter === 'all' ? 'All statuses' : ucfirst($statusFilter) . ' only' ?></small></article><article class="stat-card stat-highlight"><span>Outstanding balance</span><strong><?= e(money($outstandingBalance)) ?></strong><small><?= number_format($activeLoans) ?> approved or active loans</small></article><article class="stat-card"><span>Repayment records</span><strong><?= number_format(count($repayments)) ?></strong><small>Payment references recorded</small></article></section><?php if ($user['role'] === 'admin'): ?><section class="panel form-panel loan-import"><div class="section-heading"><div><p class="eyebrow">Payroll deductions</p><h2>Import loan deductions</h2></div><a class="text-link" href="index.php?page=loan_deductions_template">Download CSV template</a></div><p class="muted">Upload one repayment per row. Required CSV columns: <strong>staff_id, loan_reference, amount, payment_reference</strong>. Use the loan reference shown below, for example <span class="mono">LOAN-000001</span>. The import stops if any row has an invalid loan, duplicate payment reference, or amount above the remaining balance.</p><form method="post" enctype="multipart/form-data" class="form-stack"><?= csrf_field() ?><input type="hidden" name="action" value="import_loan_deductions"><label>Loan deductions CSV<input type="file" name="loan_deductions_csv" accept=".csv,text/csv" required><small>Example: ASUP-0001, LOAN-000001, 5000.00, PAYROLL-OCT-001</small></label><button class="button button-primary" type="submit">Validate and import deductions</button></form></section></div><?php endif; ?>
<section class="section-block"><div class="section-heading"><div><p class="eyebrow">Loan history</p><h2><?= $user['role'] === 'admin' ? 'Loan applications and balances' : 'Your applications and balances' ?></h2></div></div>
<?php if ($user['role'] === 'admin'): ?><form method="get" class="panel form-panel loan-filter"><input type="hidden" name="page" value="loans"><div class="form-row"><label>Find a member<input name="member" value="<?= e($memberSearch) ?>" placeholder="Name or staff ID"></label><label>Loan status<select name="status"><?php foreach ($loanStatuses as $status): ?><option value="<?= e($status) ?>"<?= $statusFilter === $status ? ' selected' : '' ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select></label></div><div class="button-row"><button class="button button-primary" type="submit">Apply filters</button><a class="button button-outline" href="index.php?page=loans">Clear filters</a></div></form><?php else: ?><div class="filter-tabs"><?php foreach ($loanStatuses as $status): ?><a class="<?= $statusFilter === $status ? 'active' : '' ?>" href="index.php?page=loans<?= $status === 'all' ? '' : '&status=' . e($status) ?>"><?= e(ucfirst($status)) ?></a><?php endforeach; ?></div><?php endif; ?>
<section class="panel"><div class="table-wrap"><table><thead><tr><?php if ($user['role'] === 'admin'): ?><th>Member</th><?php endif; ?><th>Reference</th><th>Requested</th><th>Purpose</th><th>Approved</th><th>Repaid / due</th><th>Applied</th><th>Status / action</th></tr></thead><tbody><?php if (!$loans): ?><tr><td colspan="<?= $user['role'] === 'admin' ? 8 : 7 ?>" class="empty-state">No loan applications found for these filters.</td></tr><?php endif; ?><?php foreach ($loans as $loan): $principal = (float)($loan['principal_amount'] ?? 0); $remaining = max(0, $principal - (float)$loan['repaid']); ?><tr><?php if ($user['role'] === 'admin'): ?><td><strong><?= e($loan['full_name']) ?></strong><small class="table-subtitle"><?= e($loan['staff_id']) ?></small></td><?php endif; ?><td class="mono">LOAN-<?= str_pad((string)(int)$loan['id'], 6, '0', STR_PAD_LEFT) ?></td><td><?= e(money($loan['requested_amount'])) ?></td><td><?= e($loan['purpose']) ?></td><td><?= $loan['principal_amount'] !== null ? e(money($principal)) : '—' ?></td><td><?= $loan['principal_amount'] !== null ? e(money($loan['repaid'])) . ' repaid · ' . e(money($remaining)) . ' due' : '—' ?></td><td><?= e(date('M j, Y', strtotime($loan['created_at']))) ?></td><td><?= status_badge($loan['status']) ?>
<?php if ($user['role'] === 'admin' && $loan['status'] === 'pending'): ?><form method="post" class="review-form"><?= csrf_field() ?><input type="hidden" name="action" value="review_loan"><input type="hidden" name="loan_id" value="<?= (int)$loan['id'] ?>"><label>Approve amount (₦)<input type="number" name="approved_amount" min="0.01" max="<?= e($loan['requested_amount']) ?>" step="0.01" value="<?= e($loan['requested_amount']) ?>"></label><label>Disbursement payment reference<input name="payment_reference" maxlength="190"></label><div class="inline-actions"><button class="button button-primary button-tiny" name="decision" value="approved" type="submit">Approve</button><button class="button button-danger button-tiny" name="decision" value="rejected" type="submit">Reject</button></div></form><?php elseif ($user['role'] === 'admin' && in_array($loan['status'], ['approved', 'active'], true)): ?><form method="post" class="review-form"><?= csrf_field() ?><input type="hidden" name="action" value="record_repayment"><input type="hidden" name="loan_id" value="<?= (int)$loan['id'] ?>"><label>Repayment (₦)<input name="amount" type="number" min="0.01" max="<?= e($remaining) ?>" step="0.01" required></label><label>Payment reference<input name="payment_reference" maxlength="190" required></label><button class="button button-outline button-tiny" type="submit">Record payment</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></section>
<section class="section-block panel"><div class="section-heading"><div><p class="eyebrow">Repayment control</p><h2>Repayment history</h2></div></div><div class="table-wrap"><table><thead><tr><?php if ($user['role'] === 'admin'): ?><th>Member</th><th>Staff ID</th><?php endif; ?><th>Payment reference</th><th>Amount received</th><th>Payment date</th></tr></thead><tbody><?php if (!$repayments): ?><tr><td colspan="<?= $user['role'] === 'admin' ? 5 : 3 ?>" class="empty-state">No loan repayments have been recorded.</td></tr><?php endif; ?><?php foreach ($repayments as $repayment): ?><tr><?php if ($user['role'] === 'admin'): ?><td><?= e($repayment['full_name']) ?></td><td><?= e($repayment['staff_id']) ?></td><?php endif; ?><td class="mono"><?= e($repayment['payment_reference']) ?></td><td class="amount-positive"><?= e(money($repayment['amount'])) ?></td><td><?= e(date('M j, Y H:i', strtotime($repayment['paid_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
